//+------------------------------------------------------------------+
//| Modify Position SLTP                                             |
//+------------------------------------------------------------------+
bool ModifyPositionSLTP(ulong ticket, double new_sl, double new_tp, string reason)
{
   if(!PositionSelectByTicket(ticket)) return false;
   
   new_sl = NormalizeDouble(new_sl, _Digits);
   new_tp = NormalizeDouble(new_tp, _Digits);
   
   MqlTradeRequest request;
   MqlTradeResult result;
   ZeroMemory(request);
   ZeroMemory(result);
   
   request.action   = TRADE_ACTION_SLTP;
   request.position = ticket;
   request.symbol   = PositionGetString(POSITION_SYMBOL);
   request.sl       = new_sl;
   request.tp       = new_tp;
   request.magic    = MagicNumber;
   request.comment  = reason;
   
   if(!OrderSend(request, result))
   {
      Print("Modify failed #", ticket, " err=", _LastError);
      return false;
   }
   else if(result.retcode == TRADE_RETCODE_DONE || result.retcode == TRADE_RETCODE_NO_CHANGES)
   {
      Print("Modified SL/TP #", ticket, " SL=", DoubleToString(new_sl, _Digits),
            " TP=", DoubleToString(new_tp, _Digits), " (", reason, ")");
      return true;
   }
   else
   {
      Print("Modify retcode failed #", ticket,
            " retcode=", result.retcode, " comment='", result.comment, "'");
      return false;
   }
}

//+------------------------------------------------------------------+
//| Close All Positions                                              |
//+------------------------------------------------------------------+
int CloseAllPositions(string reason = "")
{
   int closed_count = 0;
   int total = PositionsTotal();
   
   for(int i = total - 1; i >= 0; i--)
   {
      ulong ticket = PositionGetTicket(i);
      if(ticket==0) continue;
      // v14.13 A7: Only close this EA's positions on this symbol
      if(!PositionSelectByTicket(ticket)) continue;
      if(PositionGetInteger(POSITION_MAGIC)!=MagicNumber) continue;
      if(PositionGetString(POSITION_SYMBOL)!=_Symbol)    continue;
      if(ClosePositionAtMarket(ticket, reason)) closed_count++;
   }
   
   return closed_count;
}

