   // Helper macro-like logic for reading edits
   double val;
   
   if(ObjectFind(0, "SET_EDIT_Risk") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_Risk", OBJPROP_TEXT));
      if(val > 0) Runtime_RiskPerTradePct = val;
   }
   if(ObjectFind(0, "SET_EDIT_DLoss") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_DLoss", OBJPROP_TEXT));
      if(val > 0) Runtime_DailyLossLimitPct = val;
   }
   if(ObjectFind(0, "SET_EDIT_TLL") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_TLL", OBJPROP_TEXT));
      if(val > 0) Runtime_MaxTrailingDDPct = val;
   }
    if(ObjectFind(0, "SET_EDIT_DGain") >= 0) {
       val = StringToDouble(ObjectGetString(0, "SET_EDIT_DGain", OBJPROP_TEXT));
       if(val > 0) {
           Runtime_DailyGainTargetPct = val;
           Runtime_DailyGainTarget = WorkingAccountSize * (Runtime_DailyGainTargetPct / 100.0);
           // v14.17 Mod2B: recalculate limits; unblock if target not yet reached
           if(DailyTargetReached && CurrentEquity < PriorDayClose + Runtime_DailyGainTarget)
              { DailyTargetReached = false; DailyTargetBreachTime = 0; GainTargetAlertSent = false; }
           RecalculateLimits();
       }
    }
   if(ObjectFind(0, "SET_EDIT_TTG") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_TTG", OBJPROP_TEXT));
      if(val > 0) Runtime_TotalTargetGainPct = val;
   }
   if(ObjectFind(0, "SET_EDIT_TFS") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_TFS", OBJPROP_TEXT));
      if(val > 0) Runtime_TFShieldPercentage = val;
   }
   if(ObjectFind(0, "SET_EDIT_PDC") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_PDC", OBJPROP_TEXT));
      if(val >= 0) Manual_PriorDayClose = val;
   }
   if(ObjectFind(0, "SET_EDIT_HWM") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_HWM", OBJPROP_TEXT));
      if(val >= 0) Manual_HighWaterMark = val;
   }
   if(ObjectFind(0, "SET_EDIT_SBal") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_SBal", OBJPROP_TEXT));
      if(val >= 0) {
         Manual_StartingBalance = val;
         WorkingAccountSize = val; // TASK 3: Sync Original Size
      }
   }
   if(ObjectFind(0, "SET_EDIT_NewsPre") >= 0) {
      val = (double)StringToInteger(ObjectGetString(0, "SET_EDIT_NewsPre", OBJPROP_TEXT));
      if(val >= 0) Runtime_NewsPreMinutes = (int)val;
   }
   if(ObjectFind(0, "SET_EDIT_NewsPost") >= 0) {
      val = (double)StringToInteger(ObjectGetString(0, "SET_EDIT_NewsPost", OBJPROP_TEXT));
      if(val >= 0) Runtime_NewsPostMinutes = (int)val;
   }
   if(ObjectFind(0, "SET_EDIT_Scale") >= 0) {
      val = StringToDouble(ObjectGetString(0, "SET_EDIT_Scale", OBJPROP_TEXT));
      if(val > 0.1) Runtime_GuiScale = val;
   }
   
   RecalculateLimits();
   RecalculateBuffers();
}

