{
   ObjectsDeleteAll(0,"TF_"); ObjectsDeleteAll(0,"BTN_"); ObjectsDeleteAll(0,"LBL_");
   ObjectsDeleteAll(0,"GUI_"); ObjectsDeleteAll(0,"M_");  ObjectsDeleteAll(0,"SET_");
